from test_bufftap import test, tests
from test_nearby import setup

B="local B=BuffTap; "
test('Friends get a heart tag in the name field and the buff icon stays',setup+"BuffTap.db.nearbyShowAll=true; C_FriendList={IsFriend=function(g) return true end}; refresh(); BuffTap:UpdateNearbyWindow(); local row=BuffTap.nearbyFrame.rows[1]; assert(row.entry.social=='friend' and row.tags[1].shown and row.tags[1].texture:find('UIFriend',1,true) and row.icons[1].shown)")
test('Guild members get a shield tag',setup+"C_FriendList=nil; UnitIsInMyGuild=function(u) return u=='nameplate1' end; refresh(); BuffTap:UpdateNearbyWindow(); local row=BuffTap.nearbyFrame.rows[1]; assert(row.entry.social=='guild' and row.tags[1].texture:find('UIGuild',1,true)); UnitIsInMyGuild=nil")
test('Social tags can be turned off',setup+"UnitIsInMyGuild=function() return true end; BuffTap.db.nearbyMarkSocial=false; refresh(); BuffTap:UpdateNearbyWindow(); assert(BuffTap.nearbyFrame.rows[1].entry.social==nil and not BuffTap.nearbyFrame.rows[1].tags[1].shown); UnitIsInMyGuild=nil")
test('PvP flag shows with protection off while the buff stays offered',setup+"BuffTap.db.pvpProtection=false; UnitIsPVP=function(u) return u=='nameplate1' end; UnitIsPVPFreeForAll=function() return false end; refresh(); BuffTap:UpdateNearbyWindow(); local row=BuffTap.nearbyFrame.rows[1]; assert(row.entry.marker=='pvp' and row.tags[1].shown and row.icons[1].shown and BuffTap.action and BuffTap.action.nearby); assert((BuffTap.nearbyCounts.flagged or 0)==0)")
test('Idle dash is a centred texture in the first buff slot',setup+"BuffTap.db.nearbyShowAll=true; aura('nameplate1',5232,'Mark of the Wild'); aura('nameplate1',467,'Thorns'); refresh(); BuffTap:UpdateNearbyWindow(); local row=BuffTap.nearbyFrame.rows[1]; assert(row.idle.shown and row.idle.texture:find('UIDash',1,true))")
test('Default buff timing follows the buff length',B+"local long=B:FindBuff('gotw'); local short={key='x-short',name='Short Thing'}; B:NoteBuffDuration('Short Thing',60); assert(B:DefaultRebuffSeconds(long,45)==300 and B:DefaultRebuffSeconds(short,45)==0 and B:DefaultRebuffSeconds(B:FindBuff('motw'),45)==45 and B:DefaultRebuffSeconds(B:FindBuff('natures-grasp'),45)==0)")
test('Own buff timing can be zero (when gone) up to ten minutes',B+"B.db.buffSeconds.motw=0; B:InitDB(); assert(B.db.buffSeconds.motw==0); B.db.buffSeconds.motw=900; B:InitDB(); assert(B.db.buffSeconds.motw==600 and B:RebuffSeconds(B:FindBuff('motw'))==600)")
test('Header switches sit at the right edge with the label first',B+"B:Options(); local f=B.options; assert(f.nearbyEnable.headerSwitch and f.friendlyTarget.headerSwitch and f.weaponEnable.headerSwitch and f.campingEnable.headerSwitch)")
test('Motion effects run without the soft glow and orbit moves',B+"B.db.effectStyle='orbit'; B.button.buffTapEffectKey=nil; B:ApplyIconEffect(B.button,true); assert(not B.button.glow.shown and B.button.btOrbit and B.button.btOrbit.region.shown); local fx=B.button.btOrbit; local a=fx.angle; fx.region.scripts.OnUpdate(fx.region,.5); assert(fx.angle~=a); B.db.effectStyle='shine'; B:ApplyIconEffect(B.button,true); assert(not B.button.glow.shown and not fx.region.shown)")
test('Nearby page carries the guide and appearance moved to Customization',B+"B:Options(); local f=B.options; assert(f.appearancePanes.nearby and f.appearanceTabs.nearby and f.nearbyFontButton:GetParent()==f.appearancePanes.nearby and f.nearbyManaFloor.visualKey=='nearbyManaFloor')")
test('Deleting a profile other characters use asks with a warning',B+"B:Options(); local p=B.options.profiles; local old=B.profileDB:GetCurrentProfile(); B.profileDB.sv.profileKeys.Alt=old; B:CreateSettingsProfile('Second',false); p.deleteName=old; p.delete.scripts.OnClick(p.delete); assert(p.confirm.shown and p.confirmText.text:find('other character',1,true))")
test('Font menus draw each name in its own font',"local B=BuffTap; local list=B:NearbyFonts(); local arial; for _,c in ipairs(list) do if c.key=='arialn' then arial=c end end; assert(arial and arial.font=='Fonts\\\\ARIALN.TTF'); local base={GetFont=function() return 'x',12,'' end}; local btn={}; btn.GetNormalFontObject=function() return base end; btn.SetNormalFontObject=function(_,o) btn.normal=o end; local made; CreateFont=function() local o={}; o.SetFont=function(_,p) made=p end; return o end; B:PreviewChoiceFont(btn,arial.font); assert(made=='Fonts\\\\ARIALN.TTF' and btn.choiceFont and btn.normal); B:PreviewChoiceFont(btn,nil); assert(btn.normal==base and not btn.choiceFont); B:Options()")
test('Mana reserve crossing re-checks Nearby',"local B=BuffTap; B.db.nearbyManaFloor=30; UnitPower=function() return 20 end; UnitPowerMax=function() return 100 end; B.manaFloorState=false; B.nearbySnapshot={}; B.events.scripts.OnEvent(nil,'UNIT_POWER_UPDATE','player'); assert(B.manaFloorState==true and B.nearbySnapshot==nil)")
test('First Nearby intro turns on everything except buff requests',"local B=BuffTap; B:ShowNearbyIntro(true); local on={}; for _,c in ipairs(B.nearbyIntro.checks) do on[c.key]=c:GetChecked() end; assert(on.nearbyInvites and on.nearbyShowAll and not on.nearbyRequests)")
test('Hidden Nearby title bar keeps the gold line',"local B=BuffTap; B:Options(); B.db.nearbyEnabled=true; B:UpdateNearbyWindow(); local f=B.nearbyFrame; if not f then return end; for _,o in ipairs({f.title,f.line}) do o.SetAlpha=function(self,a) self.alpha=a end end; B.db.nearbyHideHeader=true; f.IsMouseOver=function() return false end; B:UpdateNearbyHeaderFade(true); assert(f.title.alpha==0 and f.line.alpha==1); B.db.nearbyKeepLine=false; B:UpdateNearbyHeaderFade(true); assert(f.line.alpha==0)")
